// @grant        none
// ==/UserScript==
!(function () {
  "use strict";

  const END_VERSION="20261021-1";
const END_MANIFEST={"鸣潮副本":{"01-万象新声·上篇":[{"id":"C01","text":"无音区强敌已被实际击败，同行者已脱离本次封锁与直接危险。"},{"id":"C02","text":"肉身纳骸的异常已发生并被同行者观察到；身份原因仍保留为待查。"},{"id":"C03","text":"今汐的寻客留言已经收到，赴今州的行动方向已确定并开始离开云陵谷。"}],"02-万象新声·下篇":[{"id":"C01","text":"坚岩斗士的复现实验已经结束，并确认此次没有再次触发肉身纳骸。"},{"id":"C02","text":"普通声骸已用终端完成回收、装配或等效功能验证。"},{"id":"C03","text":"队伍实际抵达今州城前，边庭接待与研究院检查的下一步分工已明确。"}],"03-嘤鸣初相召篇":[{"id":"C01","text":"边庭信物和相应权限已经领取，研究院的检查实际完成。"},{"id":"C02","text":"日晷配件、紫叶检测结果、糖丸关联的旧战档案已取得，三条线索均有调查结果。"},{"id":"C03","text":"本轮信物结论已汇总，队伍已经离院休息；不是只约定稍后检测。"}],"04-撞金止行阵篇":[{"id":"C01","text":"侦查塔风波已解决，塔的监测功能得到恢复，伤兵接应已完成。"},{"id":"C02","text":"致远已找到，其随军风险与后续去向已经处理，鉴心决定留营帮助今州。"},{"id":"C03","text":"莽吉柿调查和战场幻视已告一段落，漂泊者与秧秧明确转查紫叶及祈池村。"}],"05-奔策候残星篇":[{"id":"C01","text":"祈池村现场证据与伤痕的招揽已经经历，来客已突破伤痕幻境并与秧秧重新会合。"},{"id":"C02","text":"退水通路已开启，女孩的日记已找到并读出村长控制她的关键事实。"},{"id":"C03","text":"村庄悲剧的调查结论已形成，二人携证据返城或已安排上报；未把伤痕寓言当唯一真相。"}],"06-庭际刀刃鸣篇":[{"id":"C01","text":"日晷与数据库通道已经解开，今汐的秘密会面内容已通过实际会面或回叙交付。"},{"id":"C02","text":"伤痕及异生梦魇的冲突已结束，伤痕已被拘捕，审讯情报已取得。"},{"id":"C03","text":"漂泊者转查黑花、今汐前往寻角的分途安排已经落实；不是仍停在准备设伏。"}],"07-欲知天将雨篇":[{"id":"C01","text":"黑花调查已引出黑海岸人员，漂泊者已与秋水、安可建立本次调查合作。"},{"id":"C02","text":"稷廷实验室的关键记录已查明，地下机械敌人已击败，数据信标调查已有结果。"},{"id":"C03","text":"今州遭残象潮攻击的警报已收到，队伍已结束遗址调查并转入返城应战。"}],"08-千里卷戎旌篇":[{"id":"C01","text":"今州前哨支援与被困士兵救援已落实，主力没有仍困在尚未处理的城防危机中。"},{"id":"C02","text":"漂泊者已与忌炎会合、击败云闪之鳞，突入鸣式核心的部署已确定。"},{"id":"C03","text":"凿空炮台的救援、能源接口修复及充能防守已完成，炮台已具备支援突入的条件。"}],"09-千里卷戎旌篇":[{"id":"C01","text":"队伍已突破峡谷和悬浮废墟，炮击开路与同伴断后已实际完成。"},{"id":"C02","text":"无冠者重组、月亮核心及无妄者的战斗已解决，无妄者被击败并按本线结果处理。"},{"id":"C03","text":"队伍已撤出崩塌的天悬烽火，鸣式逃离与无妄者败亡的结果已分别说明。"}],"10-千里卷戎旌篇":[{"id":"C01","text":"北落野战斗已结束，街头战后说书及岳辉相认的交谈已实际发生。"},{"id":"C02","text":"漂泊者已听到民间传唱与居民对雨停的反应，本段战后安宁已收束；不要求新增战斗。"}],"11-行路遇新知篇":[{"id":"C01","text":"伙伴已经在攀花饭馆重聚，对体内出现的小家伙有过实际交流。"},{"id":"C02","text":"阿布的称呼、同行身份和待查能力已说明，聚餐已结束并进入数日后的过渡。"}],"12-梦境遗尘篇":[{"id":"C01","text":"梦境、阿布异常频率与乘霄山线索已引向边庭求证。"},{"id":"C02","text":"散华已说明今汐失联及保密要求，漂泊者已决定赴渡口并离开边庭。"}],"13-远赴乘霄篇":[{"id":"C01","text":"与长离完成渡口会合，入山风险与同行选择已经交代。"},{"id":"C02","text":"隙光滩溯流仪、撷光锁及残星会伏击已解决，二人实际穿过时流结界。"},{"id":"C03","text":"队伍已抵达虹镇，不是只看到远处镇子或刚开始赶路。"}],"14-山间古镇篇":[{"id":"C01","text":"虹镇空镇痕迹已调查，瀑后避难所已进入并与辛夷及镇民取得联系。"},{"id":"C02","text":"已确认今汐救人后先行、取心核才能开启眠龙庭的因果关系。"},{"id":"C03","text":"镇民已有避难安排，漂泊者与长离已开始前往叩天关。"}],"15-叩天关篇":[{"id":"C01","text":"叩天关三层曜岩的封锁已解除，取得心核所需的路径条件已具备。"},{"id":"C02","text":"关于角缺频、时流孤岛及二次共鸣方案的关键卷宗已查明，并与今汐会合。"},{"id":"C03","text":"游鳞机枢已击败，通向心核的道路已实际打开；本章尚不要求提前取得下一章心核。"}],"16-朝觐之路篇":[{"id":"C01","text":"心核已从中枢窟室取出，长离断后与二人离关的分工已经落实。"},{"id":"C02","text":"辛夷已将心核用于机枢，眠龙庭的入口已开启。"},{"id":"C03","text":"漂泊者与今汐已进入眠龙庭并确认角仍无回应，当前目标转为解除禁锢。"}],"17-眠龙庭篇":[{"id":"C01","text":"眠龙庭机关路径已恢复，三处曜岩已经处理、特殊曜纹全部熄灭。"},{"id":"C02","text":"残星会禁锢角的力场已解除，二人实际返回舱体前准备当面对话。"}],"18-时序之主篇":[{"id":"C01","text":"角已向二人解释时序死局，今汐的承担与婴儿旧事已在对话中明确。"},{"id":"C02","text":"声之领域中的命定之战已经实际结束，今汐完成意志与能力的证明。"},{"id":"C03","text":"御者权限请求与回应已落实，时序之能已让渡今汐；只提出让渡方案不算完成。"}],"19-风消雪霁篇":[{"id":"C01","text":"乘霄山时流已回正，今汐安全及返城休养安排已确认。"},{"id":"C02","text":"虹镇人的留山寿数条件已说明，漂泊者已完成与角的事后交流并返向虹镇。"},{"id":"C03","text":"乘霄山危机的当前结果已收束；不要求来客知晓残星会幕后镜头。"}],"20-月下祈愿其一·倾听之音篇":[{"id":"C01","text":"第一封受污染心愿已解码，并查明晓声对应十番而非仅靠同名猜测。"},{"id":"C02","text":"十番与九离已经直接沟通，事故、自责与被责怪的关键误解已说开。"},{"id":"C03","text":"心愿已得到本人和朋友的回应，第一阶段祈愿摊筹备已有落实或明确交接记录。"}],"21-月下祈愿其二·老人与约定篇":[{"id":"C01","text":"禾盈的心愿已读出，修远的生平与老人的悲伤已通过倾听实际了解。"},{"id":"C02","text":"节日游逛及修远留下的手册、手艺或教导影响已呈现给禾盈。"},{"id":"C03","text":"禾盈已表达愿意继续面对生活的当下选择，第二阶段筹备已有交接；不要求她立刻不再悲伤。"}],"22-月下祈愿其三·幼小的英雄梦篇":[{"id":"C01","text":"小满的心愿、秘密基地与模仿修炼的去向已查明。"},{"id":"C02","text":"山洞残象已处理，小满已经脱离直接危险并得到返回伙伴处的安排。"},{"id":"C03","text":"英雄不等于立刻觉醒共鸣力的引导已完成，小满已答应参加宵月会。"}],"23-月下祈愿其四·筹备篇":[{"id":"C01","text":"小帕索诺拉已进入，相里要父亲及帕斯卡研究困境的关键回声已被理解。"},{"id":"C02","text":"偏执合集已击败，帕斯卡的遗留心意已传达，队伍已返回现实。"},{"id":"C03","text":"相里要完成必要的独处和事后沟通，宵月会已到来并与伙伴合影；不能刚出索诺拉就跳过节日收尾。"}],"24-来自毁灭的回声篇":[{"id":"C01","text":"归墟港市指定坐标与灾难残响已调查，失联执花死亡已确认并安排遗体处理。"},{"id":"C02","text":"HL-1的异常读数已发现，并保留装置可能受骗的疑点，不擅自认定岁主死亡。"},{"id":"C03","text":"桥下异变已经发生，神秘接引者已将漂泊者引向黑海岸。"}],"25-沉匿于海浪之间的是篇":[{"id":"C01","text":"漂泊者已抵达黑海岸，专用信标已启用，与外界报平安的联络已完成。"},{"id":"C02","text":"新枝地、阿斯特莉亚之眼、移转异象所的稳定锚修复已完成。"},{"id":"C03","text":"霍德关于亡者处境的线索与守岸人相认已经发生，地下调查入口已具备。"}],"26-亘古永夜的孑遗篇":[{"id":"C01","text":"地下机器人救援及通路、密钥、污染障碍已处理，已接触收容中的噬亡星。"},{"id":"C02","text":"噬亡星逸出数据已制压，奇点核心已实际取得。"},{"id":"C03","text":"守岸人本体与虚影的状态已明确，来客已抵调律大厅外并击退聚集残象。"}],"27-若能在过去夺回明天篇":[{"id":"C01","text":"核心已放入调律流程，归墟星图内的城市毁灭记录与霍德质问已实际经历。"},{"id":"C02","text":"守岸人被卷入核心的结果已确认，常规调律未能救回她。"},{"id":"C03","text":"旧日志、黑花及调律者已恢复来客管理员权限，救援方案得到成员支持并具备深入系统的条件。"}],"28-便能在如今走向未来篇":[{"id":"C01","text":"漂泊者已实际突破泰缇斯内部防卫，抵达数据中枢洪流。"},{"id":"C02","text":"无归的谬误已击败，守岸人已经从编码核心中救回。"},{"id":"C03","text":"沙滩重逢与旧循环代价的事后交流已完成，亡者与守岸人的当前结果已说明。"}],"29-海岸尽头……之后？篇":[{"id":"C01","text":"本章发生在守岸人获救之后，战后等待已满足，双方已经在花房重逢。"},{"id":"C02","text":"阿布检索、替代底层频率及未来同行的交谈已完成；不以再次修复系统为结束要求。"}],"30-如一叶小舟穿行于茫茫海洋篇":[{"id":"C01","text":"黑海岸的旧信息、阿布调查进展与莫塔里邀请已交付，出海行动实际开始。"},{"id":"C02","text":"海上残象危机已解决，漂泊者已与愚人剧团接触并到达拉古那港。"},{"id":"C03","text":"入境时阿布、终端和声骸的审查插曲已处理，菲比已引导来客进入城内。"}],"31-那神圣微风时常吹入篇":[{"id":"C01","text":"资助领取和赞妮护卫关系已建立，餐厅失控刀伶已被制止并留下求助线索。"},{"id":"C02","text":"胶片、面具店与家族动向已调查，吉尔贝和教堂往来的线索已落实。"},{"id":"C03","text":"二人已穿过后花园、抵达忏悔室隐秘通路；不以只怀疑修会结束调查段。"}],"32-夜与昼，均请摘下面纱篇":[{"id":"C01","text":"失踪声骸与污染线索已查明，菲比已加入，罗蕾莱受控及云海威胁已明确。"},{"id":"C02","text":"云中庭院入口已由圣女咏叹调开启，噩梦中的罗蕾莱已击败并恢复使命。"},{"id":"C03","text":"云海当前危机已暂止，狂欢节集体祈愿与誓约仪式的沟通条件已告知。"}],"33-夜与昼，均请摘下面纱篇":[{"id":"C01","text":"金库分路潜入及关键安保障碍已完成，两人已会合并取得调音师证词。"},{"id":"C02","text":"私人终端愿景、声骸彩窗与废弃高塔线索已调查，少女神启者预言已复原。"},{"id":"C03","text":"修会阻截已实际应对，漂泊者已从高塔冲突脱身并转往悲叹墓岛。"}],"34-昔我悲伤，今却歌唱篇":[{"id":"C01","text":"已在墓岛与洛可可及布兰特会合，朝圣船的危险已查明，叹息古龙已击败并实施救援。"},{"id":"C02","text":"造云机已修复，巴多里奥的升空事故已处理，队伍实际回到剧团据点。"},{"id":"C03","text":"珂莱塔与剧团已达成演出合作，序幕彩排已完成并约好返城准备。"}],"35-昔我悲伤，今却歌唱篇":[{"id":"C01","text":"狂欢节舞台的赫卡忒战斗已结束，演出完成，漂泊者实际获得桂冠。"},{"id":"C02","text":"狂欢顶点已与卡提希娅接触，倒悬高塔的指引已获得。"},{"id":"C03","text":"次日芬莱克会面及离教堂后的复盘已完成，圣女双重身份的矛盾与后续调查方向已明确。"}],"35A-叶落无声篇":[{"id":"C01","text":"已完成金库接头与护送介入，分层权限、安全模块被取走及冒名者与老艾许的区别已通过调查明确。"},{"id":"C02","text":"研究者居住区、名册或残响的调查已完成，书页声骸的0622密码门已开启，队伍已经到达后续通路而非仍困在坠车处。"},{"id":"C03","text":"最终站危机中嫌疑人、安全模块及解除封锁的实际处理结果均已记录，队伍已安全脱困；源文缺失不能直接视为自动成功。"},{"id":"C04","text":"赞妮关于树与炸弹的调查结论、向珂莱塔汇报的结果，以及菲比目送与反思的事后交流已交付。"}],"35B-老人鱼海篇":[{"id":"C01","text":"裴魁德号已修复，风暴碑文已解，队伍已实际登上莱耶斯最后的小岛。"},{"id":"C02","text":"三处馈赠与幽灵谜题已处理，莱耶斯灯塔已点亮；若采用四塔齐明的结论，其余灯塔已有真实前置或补行记录，并完成鲸与海妖关系调查。"},{"id":"C03","text":"亚哈留言及斯塔巴克斯独自出航的情况已查明，裴魁德号已进入风暴并完成本次实际危机处置与队伍安全收束，不用原文缺失替代行动。"},{"id":"C04","text":"休整后的小岛会面已完成，阿布翻译确认鲸的康复与海妖吸收残响的事实，菲比已作个人道歉并得到鲸的回应。"}],"36-圣者，忤逆者，告死者篇":[{"id":"C01","text":"拯救、联结、向上三塔的剑与石座机制已完成，卡提希娅分离自身和寄放力量的旧事已揭明。"},{"id":"C02","text":"圣授厅的芙露德莉斯战斗已解决，来客与卡提希娅完成共同选择而非仅接受自毁方案。"},{"id":"C03","text":"英白拉多以最后力量救回卡提希娅，阿布已稳定，众人已回地面并完成与坎特蕾拉的善后交流。"}],"37-荣耀暗面篇":[{"id":"C01","text":"阿维纽林失联线索已确认，漂泊者已经进入七丘并与露帕组队。"},{"id":"C02","text":"特别选拔赛的伏尔甘矿业与缥浪已击败，冠军赛参赛资格已取得。"},{"id":"C03","text":"城区与特库斯水域的寻人调查已有结果，未能联结卡提希娅的现状已明确。"}],"38-荣耀暗面篇":[{"id":"C01","text":"弗洛洛三日剧本的威胁已经交付，漂泊者没有把预言当作已发生事实。"},{"id":"C02","text":"半决赛繁枝获胜及铜镜里的蜜芽旧事已实际经历，家族操控线索已揭出。"},{"id":"C03","text":"血色决赛和受控亚狮诺索的战斗已结束，二人夺冠并见到剧作家现形；尚未提前结算荣耀之间终局。"}],"39-燃烧的心篇":[{"id":"C01","text":"荣耀古道、露帕主动追查及铜镜实验记录已交付，杀死露帕的诱导陷阱已识破。"},{"id":"C02","text":"海之女及覆盖现实的计划已被实际制止，露帕与卡提希娅均已确认脱险。"},{"id":"C03","text":"多轮经历已互通，岩间中枢缺频和卡提希娅需检查的后续方向已明确。"}],"40-捕梦于神秘园中篇":[{"id":"C01","text":"黑海岸已报告卡提希娅失衡、残存鸣式频率与目标坐标，出海准备已落实。"},{"id":"C02","text":"漂泊者已经驶向指定海域，并与芬莱克引出的新计划正面接触。"}],"41-捕梦于神秘园中篇":[{"id":"C01","text":"隐海试验场的封锁处境与宝石争夺已查明，和弗洛洛的临时合作已实际建立。"},{"id":"C02","text":"外层调律台、轨道和修会封锁已突破，队伍已经进入声骸制造设施核心区。"}],"42-捕梦于神秘园中篇":[{"id":"C01","text":"公共声骸制造与破碎频率的现场已调查，故人声音对弗洛洛的影响已呈现。"},{"id":"C02","text":"本区调律已完成，监视录音已取得，二人已离开当前台继续深入。"}],"43-捕梦于神秘园中篇":[{"id":"C01","text":"已确认整座试验场由核心乐曲控制，芬莱克藏起两段曲谱。"},{"id":"C02","text":"缺谱所在的下层路线已定位并实际进入培育舱；本章不要求提前拿到下一章的两段谱。"}],"44-捕梦于神秘园中篇":[{"id":"C01","text":"双方分路找谱与借指挥棒协助已实际完成，两段缺失曲谱均已追回。"},{"id":"C02","text":"能源系统拦截已突破，合谱后的调律已恢复。"},{"id":"C03","text":"巨大索诺拉代价与双方最终争宝石的分歧已明确，队伍已沿输能管道继续前行。"}],"45-捕梦于神秘园中篇":[{"id":"C01","text":"已通过朝拜区域，来客已经进入并调查失亡彼岸的音乐会与研究记录。"},{"id":"C02","text":"故乡毁灭、残响不等于完整复生及弗洛洛合作网络已通过线索揭明。"},{"id":"C03","text":"音乐会相见与对话已经结束，确认宝石不在彼岸，二人实际再次合流追击芬莱克。"}],"46-捕梦于神秘园中篇":[{"id":"C01","text":"芬莱克代行者冲突已结束，其封住黑潮、身死和巡游天国警示已按本线结果交代。"},{"id":"C02","text":"宝石被残星会回收、弗洛洛沉海失踪的去向已确认，没有误报夺回宝石。"},{"id":"C03","text":"下一步赴七丘与总督会面的安排已确定；可选重访彼岸不列为必须完成的任务。"}],"47-铁锈，剑与烈阳篇":[{"id":"C01","text":"烈日酒馆的涅索叙诗已经听完，训练、三道试炼及少女获承认的主线经历已交付。"},{"id":"C02","text":"奥古斯塔为何托剑七丘及依靠个人力量维系规则的隐患已呈现，叙事已返回现实会面前。"}],"48-灼我以烈阳篇":[{"id":"C01","text":"总督邀约与狩原会合已经完成，三处定向锚的围猎方案已实际执行。"},{"id":"C02","text":"暴君反击与追踪已推进至更大威胁显露，确认它并非源头终点。"},{"id":"C03","text":"尤诺的消耗及休息安排已落实，队伍已经转向伪作神王与呓语镇。"}],"49-灼我以烈阳篇":[{"id":"C01","text":"呓语镇与旧日索诺拉调查已完成，纯净黑潮样本已取得并用于定位伪王。"},{"id":"C02","text":"彻地之楔的伪作神王已被实际击败，奥古斯塔没有将意志交给低语。"},{"id":"C03","text":"英白拉多遗匣已取得并有送黑海岸分析的安排，尤诺尚未结清的代价被保留。"}],"50-今夜，注定属于月亮篇":[{"id":"C01","text":"已发现众人不记得尤诺的异常，四方殿记录与来客记忆冲突已查证。"},{"id":"C02","text":"来客在混沌中与尤诺重新建立联系，并走过她的选择、月石金枝锚定及最后救援。"},{"id":"C03","text":"尤诺已在现实庆典重现并与来客重逢，花雨蜜酒中的团聚已完成；不能只在混沌中见面便判救回。"}],"51-已逝的必将归来篇":[{"id":"C01","text":"拉古那噩梦、金库黑潮造物与文明之匣的调查已完成，匣内记录已交付且队伍安全撤出。"},{"id":"C02","text":"狄萨莱海脊救援及阿维狄亚疯王冲突已处理，本轮黑潮暂受遏制。"},{"id":"C03","text":"真正代行者是漂泊者的揭示已发生，并明确必须处理其体内侵蚀与天国威胁。"}],"52-暗潮将映的黎明篇":[{"id":"C01","text":"两城与黑海岸联合、锚定界石防线及通往天国的路径已建立。"},{"id":"C02","text":"嘉贝莉娜旧路、卡提希娅潜入真相及克里斯托弗幻境已突破，同伴精神锚点已会合。"},{"id":"C03","text":"鸣式之茧及利维亚坦终战已结束，威胁受束缚，宝石已由黑海岸收容。"},{"id":"C04","text":"两城救治与重建安排、港口送别已完成，残缺频率和残星会后续仍列待查。"}],"53-独在异乡为异客篇":[{"id":"C01","text":"夏空补述的仇远参战、追查与芬莱克意识安息经过已听取，已标明属于旧战回叙。"},{"id":"C02","text":"漂泊者已在港口见到仇远，关于哥舒临的有限信息已交流并完成告别。"}],"54-曙光停摆于荒地之上篇":[{"id":"C01","text":"穗波往人循环、千咲处境及残星会实验的关键事实已调查。"},{"id":"C02","text":"虹音塔已进入，澄夏遗留线索及千咲记忆冲突已实际处理。"},{"id":"C03","text":"悲鸣循环已斩断，往人余念归家，内外裂隙通路已重新打开。"},{"id":"C04","text":"千咲已离开困局并获前往黑海岸治疗的安排；超频问题未被误写为永久治愈。"}],"55-星光流转于眼眸之间篇":[{"id":"C01","text":"千咲已完成本阶段治疗与复诊说明，并面对外界二十余年流逝的事实。"},{"id":"C02","text":"列车长咖啡厅装饰、朋友聚会及事后交流已完成。"},{"id":"C03","text":"新裂隙造成来客缺频的现象已被检测，拉海洛与母亲声音的下一站线索已交付。"}],"56-未知的既感篇":[{"id":"C01","text":"星炬学院入学材料及入境安排已获得，来客实际穿过通道到达拉海洛。"},{"id":"C02","text":"与琳奈的初遇和虚诞虫追逐已结束，二人已经摆脱追击并驶向学院。"}],"57-冰原下的星炬篇":[{"id":"C01","text":"中枢登记、与千咲重逢及N.A.N.A.体检已完成，缺频和防护上限已告知。"},{"id":"C02","text":"学生姓名、学部、证件照及学生证手续已办妥。"},{"id":"C03","text":"刻录磁带的研究院行程和载具安排已落实，隧者与阿列夫一的学院目标已介绍。"}],"58-冰原下的星炬篇":[{"id":"C01","text":"来客已经抵达研究院、与莫宁完成磁带刻录及缺频检查。"},{"id":"C02","text":"人工太阳和换日准备已介绍，海维夏探测器失控已经制止。"},{"id":"C03","text":"琳奈被问询的后续处境已明确，二人决定私下追查；不能把当场守住研究院写成全部洗清嫌疑。"}],"59-冰原下的星炬篇":[{"id":"C01","text":"增幅仪、论文、虚诞虫波形及滥用权限的证据链已取得，琳奈旧身份已坦白。"},{"id":"C02","text":"袭校磁暴的防御阵列已启动，两人已破坏虫体反应炉并击退虚诞虫。"},{"id":"C03","text":"学院当前安全已确认，校方回应及花园约定已发生，琳奈选择留下承担后续调查。"}],"60-致第二次日出篇":[{"id":"C01","text":"海维夏复盘与玛嘉事件已处理，来客与莫宁已到阿图雅营地了解日灵归源。"},{"id":"C02","text":"人工释放虚质的装置及伊摩尔线索已调查，营地和浮光林两处危机均有处理结果。"},{"id":"C03","text":"日树失去安全性的情况已确认，来客赴引日殿、莫宁查源的分工已实际开始。"}],"61-致第二次日出篇":[{"id":"C01","text":"引日殿日轮已复启，织星身份回应及原始观测数据已取得。"},{"id":"C02","text":"莫宁查明污染根系诱发炉芯坠落的试验与伊摩尔受利用的事实，并与来客汇合。"},{"id":"C03","text":"落区疏散、海维夏校准与提前部署赫利俄斯已执行，换日发射已经启动。"},{"id":"C04","text":"发射干扰导致人工观测失效，莫宁实际独入炉芯并失联；本章不得提前记换日成功。"}],"62-致第二次日出篇":[{"id":"C01","text":"漂泊者已追入炉芯，接手最后一程并将重伤莫宁救出。"},{"id":"C02","text":"赫利俄斯已成功恢复、第二次日出实际出现。"},{"id":"C03","text":"三日后的苏醒探望及共看人工太阳的约定已完成，破坏案调查仍被保留。"}],"63-远航星篇":[{"id":"C01","text":"爱弥斯现身、校方权限与赴冰原准备已落实，队伍已经找到天槎空间站。"},{"id":"C02","text":"站内液滴紊乱、权限与转移装置已稳定，污染下层已经进入。"},{"id":"C03","text":"无铭探索者已被击败并得到解脱，队伍告别站内同伴、继续朝隧者沉眠地出发。"}],"64-远航星篇":[{"id":"C01","text":"渐湖旧屋与童年往事已调查，辛吉勒姆夺核冲突和爱弥斯封闭自己的危机已实际应对。"},{"id":"C02","text":"炉芯已归还，爱弥斯频率完成重构并能被旁人观测；未被误写为原生肉体复原。"},{"id":"C03","text":"二人已经返回学院，飞行雪绒歌友会的本人演出已实际完成。"}],"65-远航星篇":[{"id":"C01","text":"虚质时空闭环、爱弥斯远行意图与坍缩期限已通过实际交流查明。"},{"id":"C02","text":"渐湖追赶与超频穿行已经发生，本次未能带回成年爱弥斯的分别已明确。"},{"id":"C03","text":"幼年落湖救援与护身符闭环已呈现，残留之壳经检查仅含稀薄频率，来客已回学院继续救援计划。"}],"66-日光落处篇":[{"id":"C01","text":"医务室密谈、父亲空坟及会长借用身份的不死外皮线索已交付。"},{"id":"C02","text":"赫斯、校长与来客的启动隧者合作已明确，空间站救援和魏尔伦冲突已处理。"},{"id":"C03","text":"娜波摩外皮被识破、会长脱身与第二份资料已确认，来客未贸然离开现行救援方向。"}],"67-影下不落的黄金篇":[{"id":"C01","text":"外来频率改变暗面的情况已调查，艾莉亚等被困学生已经救出。"},{"id":"C02","text":"西格莉卡面对自身期待与噩梦后已作出继续尽力、共同承担的选择。"},{"id":"C03","text":"暗面涡心已击败、权限恢复，换日庆典与伙伴合影已完成。"}],"68-影面颠倒的兔影篇":[{"id":"C01","text":"塞维的勋章记忆已调查，兔影诱导与外来暗面手段已识别。"},{"id":"C02","text":"来客已追入校长陷阱，洛瑟菈识破虚假剧本并保住自我与记忆能力。"},{"id":"C03","text":"兔子的记忆已读取，取得会长研究虚无及操控达妮娅的关键线索，两人已脱离本次陷阱。"}],"69-明日摇曳的绯影篇":[{"id":"C01","text":"暗面后的校长对话已完成，残星会与最终预案的议局已交付到相应知情角色。"},{"id":"C02","text":"爱弥斯新频率的证据已经收到，白鸟探查结果及绯雪需休息的状态已确认，队伍进入准备期。"}],"70-愿系铃中篇":[{"id":"C01","text":"绯雪返回穗波的本轮祓净已执行，玉露频率及往人不同愿望已实际接触。"},{"id":"C02","text":"关于玉露、铃与预取未来代价的回忆已呈现，会长的保存往人与鸣式共鸣提案已交到绯雪面前。"},{"id":"C03","text":"本轮停在危险邀约和待选局面，不将续篇告别或尚未作出的最终选择提前登记完成。"}],"71-昨夜群星篇":[{"id":"C01","text":"拟制炉芯与同步评估已落实，初探黯原受阻后磁暴危机及夜幕倒计时已明确。"},{"id":"C02","text":"各队罗伊符文已搜集回传、人员返回，磁带坐标得到解析并完成再次越界准备。"},{"id":"C03","text":"达妮娅容器危机已处理，爱弥斯与探索者刻下的数据已接回，拟制炉芯已用于驾驶隧者。"},{"id":"C04","text":"阿列夫一终战已结束、隧者升格并再隔绝威胁，爱弥斯完整频率归来，众人回到同伴身边完成善后。"}],"72-愿系铃中·续篇":[{"id":"C01","text":"拉海洛事件已经结束，绯雪已回穗波与玉露完成最后切磋、旧忆和直面告别。"},{"id":"C02","text":"玉露已得到祓净，预取未来的代价与愿望后果已说明；不把永世称号写成没有死亡代价。"}],"73-在熔解的夜空下篇":[{"id":"C01","text":"达妮娅的限定生日出行与陪同已实际完成，控制书页已处理并呈现其不稳定后果。"},{"id":"C02","text":"她返回实验设施的原因、旧记录和主动带走鸣式碎片的选择已揭示。"},{"id":"C03","text":"来客已追到设施并收到气泡留言、重逢暗号与会长观测限制的信息，确认她离开而非误判已经死亡或获救回校。"}],"74-我们选择天空篇":[{"id":"C01","text":"适格者计划终止后的学生处境、机兵等研究及秋水审查已实际调查。"},{"id":"C02","text":"记忆宫殿中艾米娅事故与校长负疚已面对，洛瑟菈重新作出承担未知与风险的选择。"},{"id":"C03","text":"董事会审查已经召开，并明确批准再次挑战天空的新方向；只提出建议或开始演讲不算获批。"}],"75-山雨欲来风满楼篇":[{"id":"C01","text":"秧秧来信与玄方袭击、炽霞重伤的前情已交付，来客已从学院回到今州取得边庭授权。"},{"id":"C02","text":"梦窟及井栈调查已实际推进，来客与穗穗失散但已通过装置确认体征仍正常。"},{"id":"C03","text":"椋羽接应和机傀异常情况已说明，巡霄环与云帛机骑权限已接入，秧秧战斗残影已显现。"}],"76-山雨欲来风满楼篇":[{"id":"C01","text":"秧秧获救入村、青彦寻剑及旧剑托付的回述已实际展开。"},{"id":"C02","text":"救民、测绘撤离、前营留信与定玄卫诱敌的行动已经交付，不只停在村内交谈。"},{"id":"C03","text":"秧秧已经历木禺展示的渊城旧战并拒绝其歪曲牺牲的论断，仍陷危险的状态与留下的追踪线索已明确。"}],"77-玄翎振壑定澜音篇":[{"id":"C01","text":"悬天构实验记录和被捕平民用途已查明，平民已从咎笼救出。"},{"id":"C02","text":"万囮牢屏障及强敌已解决，秧秧已经救回并获护送进城安排。"},{"id":"C03","text":"穗穗与心的试炼和新交易已通过回叙交付，分散的队伍已实际重聚。"}],"78-玄翎振壑定澜音篇":[{"i